import React, { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from '../../api/axios';
import '../../styles/AdminProducts.css';

const AdminLogin = ({ theme, onToggleTheme }) => {
  const navigate = useNavigate();
  const [form, setForm] = useState({ email: '', password: '' });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const isFormValid = useMemo(() => {
    return form.email.trim() && form.password.trim();
  }, [form]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    if (!isFormValid) {
      setError('Please enter both email and password.');
      return;
    }

    try {
      setLoading(true);
      const { data } = await axios.post('/api/users/login', {
        email: form.email,
        password: form.password,
      });

      if (data.user && data.user.email === 'admin@example.com') {
        localStorage.setItem('authToken', data.token);
        localStorage.setItem('authUser', JSON.stringify(data.user));
        localStorage.setItem('isAdmin', 'true');
        window.dispatchEvent(new Event('auth-change'));
        navigate('/admin/products');
      } else {
        setError('Access denied. You are not authorized as an administrator.');
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Authentication failed. Please verify credentials.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="admin-products-page" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: '100vh' }}>
      {/* Floating theme toggle */}
      <button
        onClick={onToggleTheme}
        title="Toggle dark/light theme"
        style={{
          position: 'fixed', top: '20px', right: '20px',
          width: '44px', height: '44px', borderRadius: '50%',
          border: '2px solid var(--admin-border)',
          background: 'var(--admin-card-bg)',
          color: 'var(--admin-text-main)',
          fontSize: '20px', cursor: 'pointer',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          boxShadow: 'var(--admin-shadow)', zIndex: 1000,
          transition: 'all 0.2s ease',
        }}
      >
        {theme === 'dark' ? '☀️' : '🌙'}
      </button>

      <div className="admin-controls-card" style={{ maxWidth: '400px', width: '100%', padding: '32px' }}>
        <div style={{ textAlign: 'center', marginBottom: '24px' }}>
          <h1 style={{ fontSize: '1.8rem', fontWeight: 800, margin: '0 0 8px 0', color: 'var(--admin-text-main)' }}>Admin Sign In</h1>
          <p style={{ color: 'var(--admin-text-muted)', fontSize: '0.9rem', margin: 0 }}>Secure portal login for catalog managers</p>
        </div>

        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label>Admin Email</label>
            <input
              name="email"
              type="email"
              className="form-input"
              value={form.email}
              onChange={handleChange}
              placeholder="admin@example.com"
              required
            />
          </div>

          <div className="form-group" style={{ marginBottom: '24px' }}>
            <label>Password</label>
            <input
              name="password"
              type="password"
              className="form-input"
              value={form.password}
              onChange={handleChange}
              placeholder="••••••••"
              required
            />
          </div>

          {error && (
            <div style={{ background: 'rgba(239, 68, 68, 0.1)', color: '#ef4444', padding: '10px 14px', borderRadius: '8px', fontSize: '0.85rem', fontWeight: 700, marginBottom: '16px', borderLeft: '3px solid #ef4444' }}>
              ⚠️ {error}
            </div>
          )}

          <button type="submit" className="btn btn-primary" style={{ width: '100%', padding: '12px' }} disabled={loading || !isFormValid}>
            {loading ? 'Authenticating...' : 'Sign In to Portal'}
          </button>
        </form>

        <div style={{ textAlign: 'center', marginTop: '20px' }}>
          <button onClick={() => navigate('/')} style={{ background: 'none', border: 'none', color: 'var(--admin-text-muted)', cursor: 'pointer', fontSize: '0.85rem', fontWeight: 700, textDecoration: 'underline' }}>
            Back to Storefront
          </button>
        </div>
      </div>
    </div>
  );
};

export default AdminLogin;
